    RTS

; Function: state_title (Bank #0)
state_title:
    ; DRAW_VECTOR: Draw vector asset at position
    ; Asset: init_screen (index=0, 57 paths)
    LDD #0
    TFR B,A       ; X position (low byte) — B already holds it
    STA TMPPTR    ; Save X to temporary storage
    LDD #40
    TFR B,A       ; Y position (low byte) — B already holds it
    STA TMPPTR+1  ; Save Y to temporary storage
    LDA TMPPTR    ; X position
    STA DRAW_VEC_X
    LDA TMPPTR+1  ; Y position
    STA DRAW_VEC_Y
    CLR MIRROR_X
    CLR MIRROR_Y
    CLR DRAW_VEC_INTENSITY  ; Reset: use .vec intensities
    LDX #0        ; Asset index for lookup
    JSR DRAW_VECTOR_BANKED  ; Draw with automatic bank switching
    LDD #0
    STD RESULT
    ; PRINT_TEXT: Print text at position
    LDD #-70
    STD >VAR_ARG0
    LDD #-40
    STD >VAR_ARG1
    LDX #PRINT_TEXT_STR_9120385685437879118      ; Pointer to string in helpers bank
    STX >VAR_ARG2
    JSR VECTREX_PRINT_TEXT
    LDD #0
    STD RESULT
    LDA >$C80F   ; Vec_Btns_1: bit0=1 means btn1 pressed
    BITA #$01
    BNE .J1B1_0_ON
    LDD #0
    BRA .J1B1_0_END
.J1B1_0_ON:
    LDD #1
.J1B1_0_END:
    STD RESULT
    LBEQ IF_NEXT_19
    LDD #0
    STD VAR_SCORE
    LDD #3  ; const LIVES_START
    STD VAR_LIVES
    LDD #1
    STD VAR_CURRENT_LEVEL
    JSR enter_game_start
    LBRA IF_END_18
IF_NEXT_19:
IF_END_18:
    RTS

; Function: state_game_start (Bank #0)
state_game_start:
    ; PRINT_TEXT: Print text at position
    LDD #-30
    STD >VAR_ARG0
    LDD #20
    STD >VAR_ARG1
    LDX #PRINT_TEXT_STR_78166382      ; Pointer to string in helpers bank
    STX >VAR_ARG2
    JSR VECTREX_PRINT_TEXT
    LDD #0
    STD RESULT
    ; PRINT_NUMBER(x, y, num)
    LDD #30
    STD >VAR_ARG0    ; X position
    LDD #20
    STD >VAR_ARG1    ; Y position
    LDD >VAR_CURRENT_LEVEL
    STD >VAR_ARG2    ; Number value
    JSR VECTREX_PRINT_NUMBER
    LDD #0
    STD RESULT
    ; PLAY_MUSIC("intro") - play music asset (index=4)
    LDX #4        ; Music asset index for lookup
    JSR PLAY_MUSIC_BANKED  ; Play with automatic bank switching
    LDD #0
    STD RESULT
    LDD >VAR_FRAME_TIMER
    STD TMPVAL          ; Save left operand to TMPVAL (stack-safe temp)
    LDD #1
    STD TMPPTR      ; Save right operand to TMPPTR
    LDD TMPVAL      ; Get left operand from TMPVAL
    SUBD TMPPTR     ; Left - Right
    STD VAR_FRAME_TIMER
    LDD #0
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_FRAME_TIMER
    CMPD TMPVAL
    LBLE .CMP_9_TRUE
    LDD #0
    LBRA .CMP_9_END
.CMP_9_TRUE:
    LDD #1
.CMP_9_END:
    LBEQ IF_NEXT_21
    JSR load_current_level
    LDD #2  ; const STATE_PLAYING
    STD VAR_GAME_STATE
    LBRA IF_END_20
IF_NEXT_21:
IF_END_20:
    RTS

; Function: state_playing (Bank #0)
state_playing:
    LDD >VAR_TIME_LEFT
    STD TMPVAL          ; Save left operand to TMPVAL (stack-safe temp)
    LDD #1
    STD TMPPTR      ; Save right operand to TMPPTR
    LDD TMPVAL      ; Get left operand from TMPVAL
    SUBD TMPPTR     ; Left - Right
    STD VAR_TIME_LEFT
    LDD #0
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_TIME_LEFT
    CMPD TMPVAL
    LBLE .CMP_10_TRUE
    LDD #0
    LBRA .CMP_10_END
.CMP_10_TRUE:
    LDD #1
.CMP_10_END:
    LBEQ IF_NEXT_23
    JSR on_player_death
    LBRA IF_END_22
IF_NEXT_23:
IF_END_22:
    JSR TRAMP_update_player  ; cross-bank trampoline (bank #0 -> bank #1)
    JSR TRAMP_update_snowballs  ; cross-bank trampoline (bank #0 -> bank #1)
    ; UPDATE_ENEMIES: advance enemy AI and movement
    JSR UPDATE_ENEMIES_RUNTIME
    JSR update_thaw
    JSR update_balls
    JSR ball_ball_collision
    JSR check_snowball_enemy_collision
    JSR check_player_enemy_collision
    LDD >VAR_PLAYER_Y
    STD TMPVAL          ; Save left operand to TMPVAL (stack-safe temp)
    LDD #30
    STD TMPPTR      ; Save right operand to TMPPTR
    LDD TMPVAL      ; Get left operand from TMPVAL
    SUBD TMPPTR     ; Left - Right
    STD VAR_CAMERA_Y
    LDD #0
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_CAMERA_Y
    CMPD TMPVAL
    LBGT .CMP_11_TRUE
    LDD #0
    LBRA .CMP_11_END
.CMP_11_TRUE:
    LDD #1
.CMP_11_END:
    LBEQ IF_NEXT_25
    LDD #0
    STD VAR_CAMERA_Y
    LBRA IF_END_24
IF_NEXT_25:
IF_END_24:
    LDD #-2304  ; const CAMERA_Y_MIN
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_CAMERA_Y
    CMPD TMPVAL
    LBLT .CMP_12_TRUE
    LDD #0
    LBRA .CMP_12_END
.CMP_12_TRUE:
    LDD #1
.CMP_12_END:
    LBEQ IF_NEXT_27
    LDD #-2304  ; const CAMERA_Y_MIN
    STD VAR_CAMERA_Y
    LBRA IF_END_26
IF_NEXT_27:
IF_END_26:
    ; ===== SET_CAMERA_Y builtin =====
    LDD >VAR_CAMERA_Y
    STD >CAMERA_Y    ; Store 16-bit camera Y scroll offset
    LDD #0
    STD RESULT
    JSR draw_player
    JSR draw_snowballs
    ; DRAW_ENEMIES: render all active enemies
    JSR DRAW_ENEMIES_RUNTIME
    JSR draw_hud
    JSR count_active_enemies
    STD VAR_ENEMY_COUNT
    LDD #0
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_ENEMY_COUNT
    CMPD TMPVAL
    LBLE .CMP_13_TRUE
    LDD #0
    LBRA .CMP_13_END
.CMP_13_TRUE:
    LDD #1
.CMP_13_END:
    LBEQ IF_NEXT_29
