; Function: draw_player (Bank #0)
draw_player:
    ; SET_INTENSITY: Set drawing intensity
    LDD #65
    TFR B,A         ; Intensity (8-bit) — B already holds low byte
    STA DRAW_VEC_INTENSITY  ; DSWM reads this for every path drawn
    LDD #0
    STD RESULT
    LDD #0
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_PLAYER_ON_GROUND
    CMPD TMPVAL
    LBEQ .CMP_64_TRUE
    LDD #0
    LBRA .CMP_64_END
.CMP_64_TRUE:
    LDD #1
.CMP_64_END:
    LBEQ IF_NEXT_135
    ; DRAW_VECTOR: Draw vector asset at position
    ; Asset: player_jump (index=10, 15 paths)
    LDD >VAR_PLAYER_X
    TFR B,A       ; X position (low byte) — B already holds it
    STA TMPPTR    ; Save X to temporary storage
    LDD >VAR_PLAYER_Y
    TFR B,A       ; Y position (low byte) — B already holds it
    STA TMPPTR+1  ; Save Y to temporary storage
    LDA TMPPTR    ; X position
    STA DRAW_VEC_X
    LDA TMPPTR+1  ; Y position
    STA DRAW_VEC_Y
    LDD >VAR_PLAYER_FACING
    TFR B,A
    STA MIRROR_X
    CLR MIRROR_Y
    CLR DRAW_VEC_INTENSITY  ; Reset: use .vec intensities
    LDX #10        ; Asset index for lookup
    JSR DRAW_VECTOR_BANKED  ; Draw with automatic bank switching
    LDD #0
    STD RESULT
    LBRA IF_END_134
IF_NEXT_135:
IF_END_134:
    LDD #1
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_PLAYER_ON_GROUND
    CMPD TMPVAL
    LBEQ .CMP_65_TRUE
    LDD #0
    LBRA .CMP_65_END
.CMP_65_TRUE:
    LDD #1
.CMP_65_END:
    LBEQ IF_NEXT_137
    LDD #0
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_PLAYER_VX
    CMPD TMPVAL
    LBEQ .CMP_66_TRUE
    LDD #0
    LBRA .CMP_66_END
.CMP_66_TRUE:
    LDD #1
.CMP_66_END:
    LBEQ IF_NEXT_139
    ; DRAW_VECTOR: Draw vector asset at position
    ; Asset: player_idle (index=9, 9 paths)
    LDD >VAR_PLAYER_X
    TFR B,A       ; X position (low byte) — B already holds it
    STA TMPPTR    ; Save X to temporary storage
    LDD >VAR_PLAYER_Y
    TFR B,A       ; Y position (low byte) — B already holds it
    STA TMPPTR+1  ; Save Y to temporary storage
    LDA TMPPTR    ; X position
    STA DRAW_VEC_X
    LDA TMPPTR+1  ; Y position
    STA DRAW_VEC_Y
    LDD >VAR_PLAYER_FACING
    TFR B,A
    STA MIRROR_X
    CLR MIRROR_Y
    CLR DRAW_VEC_INTENSITY  ; Reset: use .vec intensities
    LDX #9        ; Asset index for lookup
    JSR DRAW_VECTOR_BANKED  ; Draw with automatic bank switching
    LDD #0
    STD RESULT
    LBRA IF_END_138
IF_NEXT_139:
    ; DRAW_ANIM: draw animation 'player_walk'
    LDD >VAR_PLAYER_X
    TFR B,A
    STA DRAW_VEC_X
    LDD >VAR_PLAYER_Y
    TFR B,A
    STA DRAW_VEC_Y
    LDD >VAR_PLAYER_FACING
    TFR B,A
    STA >MIRROR_X
    STA >DRAW_ANIM_MIRROR_X
    CLR >MIRROR_Y
    LDA #$7F
    STA DRAW_ANIM_SCALE
    CLR DRAW_ANIM_SPEED_MUL
    LDX #_ANIM_PLAYER_WALK
    LDU #ANIM_PLAYER_WALK_STATE
    JSR DRAW_ANIM_RUNTIME
    LDD #0
    STD RESULT
IF_END_138:
    LBRA IF_END_136
IF_NEXT_137:
IF_END_136:
    RTS

