; Function: draw_hud (Bank #0)
draw_hud:
    ; PRINT_NUMBER(x, y, num)
    LDD #-10
    STD >VAR_ARG0    ; X position
    LDD #127
    STD >VAR_ARG1    ; Y position
    LDD >VAR_SCORE
    STD >VAR_ARG2    ; Number value
    JSR VECTREX_PRINT_NUMBER
    LDD #0
    STD RESULT
    ; PRINT_NUMBER(x, y, num)
    LDD #-78
    STD >VAR_ARG0    ; X position
    LDD #116
    STD >VAR_ARG1    ; Y position
    LDD >VAR_LIVES
    STD >VAR_ARG2    ; Number value
    JSR VECTREX_PRINT_NUMBER
    LDD #0
    STD RESULT
    ; PRINT_NUMBER(x, y, num)
    LDD #58
    STD >VAR_ARG0    ; X position
    LDD #127
    STD >VAR_ARG1    ; Y position
    LDD >VAR_TIME_LEFT
    STD TMPVAL          ; Save left operand to TMPVAL (stack-safe temp)
    LDD #60
    LDX TMPVAL      ; Get left into X from TMPVAL
    JSR DIV16       ; D = X / D
    STD >VAR_ARG2    ; Number value
    JSR VECTREX_PRINT_NUMBER
    LDD #0
    STD RESULT
    ; PRINT_TEXT: Print text at position
    LDD #-98
    STD >VAR_ARG0
    LDD #-110
    STD >VAR_ARG1
    LDX #PRINT_TEXT_STR_67      ; Pointer to string in helpers bank
    STX >VAR_ARG2
    JSR VECTREX_PRINT_TEXT
    LDD #0
    STD RESULT
    ; PRINT_NUMBER(x, y, num)
    LDD #-85
    STD >VAR_ARG0    ; X position
    LDD #-110
    STD >VAR_ARG1    ; Y position
    LDD >VAR_ENEMY_COUNT
    STD >VAR_ARG2    ; Number value
    JSR VECTREX_PRINT_NUMBER
    LDD #0
    STD RESULT
    RTS

; Function: check_snowball_enemy_collision (Bank #0)
check_snowball_enemy_collision:
    LDD #0
    STD VAR_I
WH_188: ; while start
    LDD #8
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_I
    CMPD TMPVAL
    LBLT .CMP_91_TRUE
    LDD #0
    LBRA .CMP_91_END
.CMP_91_TRUE:
    LDD #1
.CMP_91_END:
    LBEQ WH_END_189
    LDD #1
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_I
    TFR B,A             ; A = enemy index (low byte)
    LDB #16             ; ENEMY_POOL_STRIDE
    MUL                 ; D = A * stride
    LDX #ENEMY_POOL
